SELECT

FROM INQUIRY_ROOMS R
JOIN UNIVERSITY U ON U.UNIV_ID = R.UNIV_ID
WHERE R.INQUIRY_ROOM_ID = #{roomId}
  AND R.UNIV_ID = #{univId}

mapper.update:
UPDATE INQUIRY_MESSAGES
SET STATUS = 1
WHERE INQUIRY_ROOM_ID = #{roomId}
  AND MEMBER_ID != #{memberId}
  AND NVL(STATUS, 0) = 0

UPDATE INQUIRY_ROOMS
SET STATUS = CASE
    WHEN #{status} = 'IN_PROGRESS' THEN 'PROGRESS'
    ELSE #{status}
END
WHERE INQUIRY_ROOM_ID = #{roomId}
